var tree = get_tree()
var scene = tree.current_scene
Engine.max_fps = 120
var set_vector = func(v: Vector2):
	for axis in [JOY_AXIS_RIGHT_X, JOY_AXIS_RIGHT_Y]:
		var event = InputEventJoypadMotion.new()
		event.device = 0
		event.axis = axis
		event.axis_value = v.x if axis == JOY_AXIS_RIGHT_X else v.y
		Input.parse_input_event(event)
var wait_frames = func(count: int):
	for frame in range(count):
		await tree.process_frame
set_vector.call(Vector2.ZERO)
await wait_frames.call(3)
var results = []
for fps in [30,60,120]:
	Engine.max_fps = fps
	await wait_frames.call(3)
	set_vector.call(Vector2(0.95,0.0))
	var frames = []
	for frame in range(5):
		await RenderingServer.frame_post_draw
		frames.append({"visible":scene.flash.visible,"remaining":scene.flash_frames,"ticks_us":Time.get_ticks_usec()})
	set_vector.call(Vector2.ZERO)
	await wait_frames.call(3)
	results.append({"fps_cap":fps,"frames":frames})
Engine.max_fps = 120
return {"results":results}
